class PackedBushyOutputOverlapTest {

	private static final PackedCostModel COSTS = (query, relation) -> {
		if (query.isBindingSetAssignment(relation)) {
			return query.bindingAssignmentRowCount(relation);
		}
		if (!query.isStatementPattern(relation)) {
			return Double.NaN;
		}
		String predicate = query.statementPatternValue(relation, 1).stringValue();
		if (predicate.contains("mixed")) {
			return 10.0d;
		}
		return predicate.endsWith("p0") ? 5.0d : 1.0d;
	};

	@ParameterizedTest
	@CsvSource({ "3,false", "3,true", "4,false", "4,true", "17,false", "17,true", "65,false", "65,true" })
	void disjointOutputsRetainExactCartesianRowsAcrossSubsetWidths(int factors, boolean reversed) {
		Model data = PackedPlanDifferentialSupport.model();
		List<String> patterns = new ArrayList<>();
		patterns.add("VALUES ?u { \"u1\" \"u2\" }");
		patterns.add("VALUES ?v { \"v1\" \"v2\" \"v3\" }");
		for (int factor = 0; factor < factors - 2; factor++) {
			patterns.add("?s" + factor + " :p" + factor + " ?o" + factor + " .");
			for (int row = 0; row < (factor == 0 ? 5 : 1); row++) {
				PackedPlanDifferentialSupport.add(data, "subject" + factor + "-" + row, "p" + factor,
						PackedPlanDifferentialSupport.iri("object" + factor + "-" + row));
			}
		}
		if (reversed) {
			Collections.reverse(patterns);
		}
		TupleExpr source = PackedPlanDifferentialSupport.parse("SELECT * WHERE { " + String.join(" ", patterns) + " }");
		assertPlanRowsAndBag(data, source, 30.0d);
	}

	@ParameterizedTest
	@CsvSource({ "3,false", "3,true", "15,false", "15,true", "63,false", "63,true" })
	void mixedComponentsApplySelectivityOnlyAtActualSharedOutputs(int statements, boolean reversed) {
		Model data = PackedPlanDifferentialSupport.model();
		List<String> patterns = new ArrayList<>();
		patterns.add("VALUES ?u { \"u1\" \"u2\" }");
		patterns.add("VALUES ?v { \"v1\" \"v2\" \"v3\" }");
		for (int factor = 0; factor < statements; factor++) {
			patterns.add("?shared :mixed" + factor + " ?o" + factor + " .");
			for (int row = 0; row < 10; row++) {
				PackedPlanDifferentialSupport.add(data, "key" + row, "mixed" + factor,
						PackedPlanDifferentialSupport.iri("value" + factor + "-" + row));
			}
		}
		if (reversed) {
			Collections.reverse(patterns);
		}
		TupleExpr source = PackedPlanDifferentialSupport.parse("SELECT * WHERE { " + String.join(" ", patterns) + " }");
		// Every SP shares the ten-key component; only the two finite factors multiply its rows.
		assertPlanRowsAndBag(data, source, 60.0d);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void genuineSharedOutputsKeepTheExistingConnectedEstimate(boolean reversed) {
		Model data = PackedPlanDifferentialSupport.model();
		for (int row = 0; row < 10; row++) {
			PackedPlanDifferentialSupport.add(data, "key" + row, "mixed0",
					PackedPlanDifferentialSupport.iri("left" + row));
			PackedPlanDifferentialSupport.add(data, "key" + row, "mixed1",
					PackedPlanDifferentialSupport.iri("right" + row));
		}
		String first = "?shared :mixed0 ?left .";
		String second = "?shared :mixed1 ?right .";
		TupleExpr source = PackedPlanDifferentialSupport.parse("SELECT * WHERE { "
				+ (reversed ? second + first : first + second) + " }");
		assertPlanRowsAndBag(data, source, 10.0d);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void inheritedRequestFrameDoesNotBecomeAChildEquijoin(boolean reversed) {
		Model data = PackedPlanDifferentialSupport.model();
		for (int row = 0; row < 5; row++) {
			PackedPlanDifferentialSupport.add(data, "subject" + row, "p0",
					PackedPlanDifferentialSupport.iri("object" + row));
		}
		String finite = "VALUES ?u { \"u1\" \"u2\" } VALUES ?v { \"v1\" \"v2\" \"v3\" }";
		String pattern = "?s :p0 ?o .";
		TupleExpr source = PackedPlanDifferentialSupport.parse("SELECT * WHERE { VALUES ?request { 1 2 } "
				+ "LATERAL { " + (reversed ? pattern + finite : finite + pattern)
				+ " BIND(?request AS ?echo) } }");
		List<String> expected = PackedPlanDifferentialSupport.evaluate(data, source);
		assertEquals(60, expected.size());
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), COSTS);
		assertTrue(Double.isFinite(result.totalCost()));
		assertEquals(expected, PackedPlanDifferentialSupport.evaluate(data, result.selectedPlan()));
		List<Lateral> laterals = new ArrayList<>();
		result.selectedPlan().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Lateral lateral) {
				laterals.add(lateral);
				super.meet(lateral);
			}
		});
		assertEquals(1, laterals.size());
		TupleExpr right = laterals.getFirst().getRightArg();
		assertEquals(30.0d, right.getResultSizeEstimate(), 0.0d,
				"the provider qualifies the RHS component, not the enclosing LATERAL aggregate");
		List<StatementPattern> statements = new ArrayList<>();
		List<Set<String>> finiteHeaders = new ArrayList<>();
		right.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern statement) {
				statements.add(statement);
			}

			@Override
			public void meet(BindingSetAssignment assignment) {
				finiteHeaders.add(assignment.getBindingNames());
			}
		});
		assertEquals(1, statements.size());
		assertEquals("s", statements.getFirst().getSubjectVar().getName());
		assertEquals(PackedPlanDifferentialSupport.iri("p0"), statements.getFirst().getPredicateVar().getValue());
		assertEquals("o", statements.getFirst().getObjectVar().getName());
		assertEquals(2, finiteHeaders.size());
		assertEquals(Set.of(Set.of("u"), Set.of("v")), Set.copyOf(finiteHeaders));
		assertRequestEchoFrames(data, source);
		assertRequestEchoFrames(data, result.selectedPlan());
	}

	private static void assertRequestEchoFrames(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(
						data.getStatements(subject, predicate, object, contexts).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return PackedPlanDifferentialSupport.VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot ? (QueryRoot) expression.clone()
				: new QueryRoot(expression.clone());
		int[] frameRows = new int[2];
		try (var rows = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				assertEquals(row.getValue("request"), row.getValue("echo"));
				String request = row.getValue("request").stringValue();
				assertTrue(request.equals("1") || request.equals("2"));
				frameRows[request.equals("1") ? 0 : 1]++;
			}
		}
		assertEquals(30, frameRows[0]);
		assertEquals(30, frameRows[1]);
	}

	private static void assertPlanRowsAndBag(Model data, TupleExpr source, double expectedRows) {
		List<String> expected = PackedPlanDifferentialSupport.evaluate(data, source);
		assertEquals((int) expectedRows, expected.size(), "the public unoptimized evaluation is the exact bag oracle");
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), COSTS);
		assertTrue(Double.isFinite(result.totalCost()));
		assertEquals(expected, PackedPlanDifferentialSupport.evaluate(data, result.selectedPlan()));
		assertEquals(expectedRows, result.outputRows(), 0.0d,
				() -> "enumeration edges and common inherited reads do not certify shared output selectivity: "
						+ result.selectedPlan());
	}
}
